INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-001','WK-01',1,'أدوات السيارة',35,'{"goal":"تحديد أدوات التحكم الأساسية قبل تشغيل السيارة","introduction":"تعرفي على وظائف المقود والدواسات وناقل الحركة والإشارات؛ الهدف أن تميزي بين التحكم في الحركة وبين أدوات الراحة.","key_points":["دواسة الفرامل تقلل السرعة وتثبت السيارة","في سيارة أوتوماتيكية هناك دواسة للبنزين وأخرى للفرامل","مواقع الأزرار تتغير باختلاف سنة وفئة هوندا أكورد"],"scenario":"السيارة متوقفة في مكان آمن: أشيري إلى دواسة الفرامل وناقل الحركة دون تشغيلها.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"مواقع الأزرار تتغير باختلاف سنة وفئة هوندا أكورد"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-002','WK-01',2,'التهيئة والسلامة',35,'{"goal":"إعداد جلوس آمن قبل أي تحرك","introduction":"جلسة القيادة الصحيحة تعطيك وصولًا مريحًا للدواسات وتحكمًا بالمقود ورؤية واضحة. اضبطي المقعد والمرايا وحزام الأمان والسيارة ثابتة.","key_points":["ضعي الحزام بحيث يستقر فوق الكتف والحوض بشكل صحيح","تأكدي أن القدم تصل إلى الفرامل دون تمدد مفرط","اتركي مساحة مناسبة عن المقود والوسادة الهوائية وفق دليل السيارة"],"scenario":"قبل رحلة نظرية، رتبي فحصًا قصيرًا: المقعد ← المرايا ← الحزام ← الأبواب.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"اتركي مساحة مناسبة عن المقود والوسادة الهوائية وفق دليل السيارة"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-003','WK-01',3,'لوحة القيادة',35,'{"goal":"قراءة مؤشرات لوحة القيادة دون خلطها","introduction":"تعرض لوحة العدادات السرعة والوقود والرسائل ومؤشرات تنبيه تختلف حسب طراز السيارة. بعض الأيقونات تظهر مؤقتًا عند تشغيل المركبة للفحص.","key_points":["ليس كل رمز مضيء عطلًا","افهمي كل تحذير في سياقه ورسالة الشاشة","لا تهملي تحذيرات الفرامل أو الزيت أو الحرارة"],"scenario":"تظهر لمبة عند تشغيل السيارة ثم تختفي بعد الفحص: هل يلزم افتراض عطل؟","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا تهملي تحذيرات الفرامل أو الزيت أو الحرارة"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-004','WK-02',4,'أجزاء الطريق',35,'{"goal":"التفريق بين الطريق والرصيف والكتف","introduction":"يتكون مقطع الطريق من أجزاء مختلفة تؤدي وظائف مختلفة؛ لا يُعد كل سطح ممهد مسارًا مخصصًا للسير.","key_points":["الرصيف أو الممشى للمشاة","كتف الطريق ليس مسار سير إضافيًا عادةً","اتبعي العلامات والأجهزة المنظمة لحركة المرور"],"scenario":"ترين كتف طريق واسعًا وسيارات أمامك بطيئة؛ هل يصبح مسارًا جديدًا؟","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"اتبعي العلامات والأجهزة المنظمة لحركة المرور"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-005','WK-02',5,'المسارات',35,'{"goal":"فهم المسار والاتجاه","introduction":"يمكن أن يحتوي الاتجاه الواحد على مسارين أو أكثر؛ والاتجاه شيء مختلف عن عدد المسارات.","key_points":["تحدّد خطوط الأرضية حدود المسارات","السهم الأرضي يحدد الحركات المسموحة من المسار","التبديل يحتاج مناورة آمنة لا مجرد مسار خالٍ ظاهر"],"scenario":"طريق بثلاثة مسارات تتجه جميعها للأمام: كم اتجاهًا للسير؟","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"التبديل يحتاج مناورة آمنة لا مجرد مسار خالٍ ظاهر"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-006','WK-02',6,'مستخدمو الطريق',35,'{"goal":"التنبّه للمشاة والدراجات والمركبات","introduction":"الطريق مساحة مشتركة؛ اختلاف حجم مستخدميه ورؤيتهم يزيد أهمية التوقع والانتظار.","key_points":["توقعي دخول المشاة قرب المدارس والمواقف","الدراجات النارية أصغر وقد يصعب تقدير بعدها","انتبهي للمركبات الكبيرة ونقاطها العمياء"],"scenario":"سيارة متوقفة قرب معبر وفي جوارها طفل: ما الاحتمال الذي تراقبينه؟","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"انتبهي للمركبات الكبيرة ونقاطها العمياء"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-007','WK-03',7,'إشارات التحذير',35,'{"goal":"تمييز وظيفة علامات التحذير","introduction":"علامات التحذير تنبهك إلى خطر أو تغير قادم؛ الشكل والرمز واللوحات الإضافية تُقرأ معًا.","key_points":["خففي سرعتك عند الحاجة قبل موقع الخطر","لا تفترضي أن كل علامة تحذير تفرض حدًا رقميًا جديدًا","اربطي الرمز بالتصرف المتوقع"],"scenario":"علامة تنبه لمنعطف خطر على طريق سريع.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"اربطي الرمز بالتصرف المتوقع"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-008','WK-03',8,'الإشارات التنظيمية',35,'{"goal":"فهم العلامات التنظيمية","introduction":"تخبرك العلامات التنظيمية بما يجب فعله أو ما يُمنع؛ مثل قف ومنع الدخول وحدود السرعة المنشورة.","key_points":["اللوحات التنظيمية تؤثر على الحركة المسموحة","اقرئي نص أو رقم اللوحة بوضوح","إذا تعارض اجتهادك مع تنظيم واضح اتبعي التنظيم"],"scenario":"وصلت إلى علامة قف والطريق يبدو خاليًا.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"إذا تعارض اجتهادك مع تنظيم واضح اتبعي التنظيم"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-009','WK-03',9,'الإشارات الإرشادية والمؤقتة',35,'{"goal":"التمييز بين اللوحات الإرشادية والمؤقتة","introduction":"الإرشادية تساعد على الاتجاه إلى وجهة أو خدمة، والمؤقتة ترتبط غالبًا بأعمال طريق أو تحذير مؤقت.","key_points":["اللوحة المؤقتة لا تُهمَل لمجرد أن الطريق مألوف","خذي قرار تغيير المسار مبكرًا وبشكل آمن","لا تقرئي لوحة طويلة على حساب مراقبة الطريق"],"scenario":"توجد لوحة مؤقتة توجّهك لمسار بسبب صيانة.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا تقرئي لوحة طويلة على حساب مراقبة الطريق"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-010','WK-04',10,'الإشارات الضوئية',35,'{"goal":"قراءة الإشارات الضوئية الأساسية","introduction":"الأحمر يقتضي التوقف، والأصفر يدعو للاستعداد للتوقف الآمن، والأخضر يسمح بالحركة ضمن الأولويات والتنظيم.","key_points":["الأخضر لا يضمن أن التقاطع فارغ","لا تدخلي تقاطعًا مسدودًا بالازدحام","السهم أو اللوحة قد يخصصان حركة دون غيرها"],"scenario":"إشارتك خضراء لكن المركبات عالقة داخل التقاطع.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"السهم أو اللوحة قد يخصصان حركة دون غيرها"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-011','WK-04',11,'التقاطعات والأولوية',35,'{"goal":"تحديد الأولوية بحسب نوع التقاطع","introduction":"الأولوية ليست قاعدة واحدة دائمًا؛ افحصي اللوحات والإشارات وتصميم الطريق قبل تحديد من يمر أولًا.","key_points":["للطرق الرئيسية أفضلية في الحالة المعتادة ما لم يوجد تنظيم مختلف","قاعدة القادم من اليمين لها ظروف محددة","رجال المرور والإشارات المنظمة يغيرون ترتيب العبور"],"scenario":"دخلت تقاطعًا من طريق فرعي وطريق رئيسي مشغول.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"رجال المرور والإشارات المنظمة يغيرون ترتيب العبور"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-012','WK-04',12,'معابر المشاة ومراجعة الشهر',35,'{"goal":"ممارسة مراجعة شهرية للمشاة والإشارات","introduction":"نراجع هنا أسس الشهر الأول بتفسير موقف، لا بحفظ شكل العلامة فقط.","key_points":["ابحثي عن معبر مشاة قبل الانعطاف","السرعة الملائمة تعتمد على الرؤية والازدحام","التوقف الصحيح أهم من الوصول السريع"],"scenario":"أنتِ تريدين الانعطاف ويوجد مشاة على المعبر.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"التوقف الصحيح أهم من الوصول السريع"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-013','WK-05',13,'أجزاء الطريق والمسارات',35,'{"goal":"تمييز أجزاء الطريق في رسمة متعددة المسارات","introduction":"المسار منطقة حركة داخل الطريق؛ الاتجاه هو وجهة الحركة. يفضّل تمثيلهما بسهم واحد للاتجاه وأسهم أصغر للمسارات.","key_points":["قد تشترك مسارات عدة في اتجاه واحد","الرصيف منطقة مشاة وليس شريط تجاوز","الكتف ليس امتدادًا طبيعيًا لمسار السير"],"scenario":"ترين ثلاثة خطوط حركة باتجاه شمال الطريق.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"الكتف ليس امتدادًا طبيعيًا لمسار السير"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-014','WK-05',14,'الخطوط المتصلة والمتقطعة',35,'{"goal":"قراءة الخطوط الأرضية دون تعميم","introduction":"شكل الخط ولونه وموقعه معًا يحدد المعنى. الخط المتقطع قد يسمح بعبوره في الظروف المناسبة، لكن لا يلغي شروط السلامة.","key_points":["الخط المتصل أو المزدوج المتصل يُمنع عبوره وفق دلالته","اللون الأبيض لا يعني بالضرورة أن الطريق في اتجاه واحد","قبل عبور أي خط افحصي المرايا والنقطة العمياء وأولوية المسار"],"scenario":"خط أبيض متقطع بين مسارين وسيارة قريبة في المجاور.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"قبل عبور أي خط افحصي المرايا والنقطة العمياء وأولوية المسار"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-015','WK-05',15,'اختيار المسار',35,'{"goal":"اختيار المسار قبل الوصول إلى التقاطع","introduction":"اختاري المسار وفق الأسهم واللوحات والوجهة، وحافظي على القرار بدل حركة أخيرة خطرة.","key_points":["خططي للخروج مبكرًا","إذا فاتك مخرج تابعي إلى مكان مناسب لإعادة المسار","لا تنعطفي من مسار للأمام فقط إذا كانت العلامات تمنع"],"scenario":"سهم مسارك للأمام فقط لكن تريدين يمينًا.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا تنعطفي من مسار للأمام فقط إذا كانت العلامات تمنع"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-016','WK-06',16,'قف وأعط الأفضلية',35,'{"goal":"الفصل بين قف وأعط الأفضلية","introduction":"قف تعني توقفًا تامًا ثم متابعة عند الأمان، وأعط الأفضلية تتطلب التخفيف وإفساح المجال وقد يلزم التوقف.","key_points":["التوقف الكامل ليس مجرد حركة بطيئة","تفقدي المشاة والمركبات قبل الدخول","لا تحولي مدة معينة إلى شرط قانوني عام دون سند"],"scenario":"هناك علامة أعط الأفضلية ولا توجد مركبة أخرى قريبة.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا تحولي مدة معينة إلى شرط قانوني عام دون سند"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-017','WK-06',17,'الإشارات الضوئية',35,'{"goal":"فهم الضوء الأخضر والانعطاف عند الأحمر","introduction":"معنى الضوء مرتبط بالأسهم وتنظيم التقاطع. لا تفترضي جواز الانعطاف يمينًا عند الأحمر في كل تقاطع.","key_points":["الأخضر لا يسمح باقتحام تقاطع مغلق","إذا وجدت لوحة أو سهم أحمر يمنع الانعطاف فلا تنعطفي","تنظيم الالتفاف عند الأحمر السعودي له شروط إضافية يجب الرجوع للنص الجاري"],"scenario":"توجد لوحة تمنع الانعطاف يمينًا عند الأحمر.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"تنظيم الالتفاف عند الأحمر السعودي له شروط إضافية يجب الرجوع للنص الجاري"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-018','WK-06',18,'أولوية التقاطعات',35,'{"goal":"تطبيق الأولوية على تقاطعات محددة","introduction":"قيّمي التنظيم أولًا: رجل مرور، إشارة، علامة، طريق رئيسي ثم قواعد تقاطعات متساوية الأولوية.","key_points":["القادم من اليمين ليست قاعدة لكل تقاطع","الانعطاف أو الدوران للخلف يحتاج فحص حركة الاتجاهات الأخرى","إذا تعذر رؤية المكان لا تدخلي بالتخمين"],"scenario":"تقاطع بلا تنظيم وطرق متساوية وتصل سيارتان في الوقت نفسه.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"إذا تعذر رؤية المكان لا تدخلي بالتخمين"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-019','WK-07',19,'أولوية الدخول إلى الدوار',35,'{"goal":"التعامل مع أفضلية المركبات داخل الدوار","introduction":"في الدوار المعتاد غير المنظم بخلاف ذلك، أعطي الأفضلية للمركبات الموجودة داخله، وادخلي عند وجود فرصة آمنة.","key_points":["قراءة حركة المركبات داخل الدوار قبل دخولك أساسية","امتلاك الأولوية لا يبرر التسبب بخطر","لا يلزم توقف كامل إن كان الدخول آمنًا ولا توجد علامة توقف"],"scenario":"ترين مركبة داخل الدوار تقترب من نقطة دخولك.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا يلزم توقف كامل إن كان الدخول آمنًا ولا توجد علامة توقف"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-020','WK-07',20,'اختيار مسار الدوار والمخرج الصحيح',35,'{"goal":"اختيار مسار الدوار حسب اللوحات والتخطيط","introduction":"لا يوجد توزيع واحد لمسارات جميع الدوارات. حددي وجهتك مبكرًا، ثم اختاري مسار الاقتراب وفق الأسهم.","key_points":["المخرج الأول لا يعني دائمًا أي مسار دون قراءة التعليمات","لا تنتقلي عبر عدة مسارات بشكل مفاجئ للوصول للمخرج","انتبهِي لعبور مشاة عند مخرج الدوار"],"scenario":"أنت داخل دوار ووجدت أنك في مسار لا يسمح بالمخرج المرغوب.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"انتبهِي لعبور مشاة عند مخرج الدوار"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-021','WK-07',21,'أولوية المشاة',35,'{"goal":"إعطاء المشاة حقهم عند المعابر","introduction":"المشاة أولوية عند عبورهم في الأماكن المخصصة. افحصي المعابر أيضًا عند خروج الدوارات والانعطاف.","key_points":["خففي السرعة عند الاقتراب من المعبر","توقفي عند الحاجة بشكل آمن","لا تفترضي خلو المعبر لمجرد خلو الطريق أمامك"],"scenario":"تخرجين من دوار وتجدين مشاة يعبرون عند المخرج.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا تفترضي خلو المعبر لمجرد خلو الطريق أمامك"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-022','WK-08',22,'تغيير المسار والنقطة العمياء',35,'{"goal":"تنفيذ تسلسل آمن لتغيير المسار","introduction":"ابدئي بالملاحظة ثم الإشارة والتحقق من المنطقة العمياء والتكيّف مع السرعة قبل الانتقال التدريجي.","key_points":["راقبي المرايا والمنطقة التي لا تظهر فيها","الإشارة لا تمنحك أولوية المسار المجاور","لا تنتقلي حتى تتوفر فجوة آمنة"],"scenario":"تشغلين الإشارة إلى اليسار وهناك مركبة بمحاذاتك.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا تنتقلي حتى تتوفر فجوة آمنة"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-023','WK-08',23,'التجاوز من اليسار أو اليمين',35,'{"goal":"فهم قاعدة التجاوز واستثناءاتها","introduction":"الأصل أن التجاوز يكون من اليسار، مع استثناءات تنظيمية محددة لا تجعل التجاوز من اليمين خيارًا آمنًا دائمًا.","key_points":["التجاوز لا يبرر زيادة السرعة فوق الحد النظامي","الاستثناء القانوني لا يغني عن شروط الرؤية والمسافة","قد يحظر المكان التجاوز بغض النظر عن عدد المسارات"],"scenario":"أمامك مركبة بطيئة لكن الطريق أمامها منحنى يحجب الرؤية.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"قد يحظر المكان التجاوز بغض النظر عن عدد المسارات"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-024','WK-08',24,'متى يكون التجاوز محظورًا؟',35,'{"goal":"تحديد حالات منع التجاوز","introduction":"راجعي المعابر والخطوط المتصلة والتقاطعات وضعف الرؤية وحدود السرعة قبل مناورة التجاوز.","key_points":["لا تتجاوزي إذا تطلب الأمر عبور خط مانع","لا تتجاوزي عند معبر مشاة","إذا بدأ سائق خلفك بالتجاوز لا تنفذي مناورة متعارضة"],"scenario":"ترين معبر مشاة أمام السيارة البطيئة.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"إذا بدأ سائق خلفك بالتجاوز لا تنفذي مناورة متعارضة"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-025','WK-09',25,'السرعة المناسبة',35,'{"goal":"اختيار سرعة تناسب الواقع لا اللوحة وحدها","introduction":"حد السرعة الأعلى سقف نظامي وليس سرعة مضمونة في كل الظروف. اختاري سرعة أدنى في المطر والازدحام وضعف الرؤية.","key_points":["المطر يؤثر على التماسك","قيّمي حركة المشاة والمركبات","إذا شككت في الرؤية خففي السرعة تدريجيًا وبشكل آمن"],"scenario":"اللوحة 80 كم/س مع ضباب كثيف.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"إذا شككت في الرؤية خففي السرعة تدريجيًا وبشكل آمن"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-026','WK-09',26,'مسافة التوقف',35,'{"goal":"حساب مسافة التوقف على نحو تقريبي","introduction":"مسافة التوقف تساوي مسافة رد الفعل زائد مسافة الفرملة. مثال الدليل التقريبي عند 80 كم/ساعة: 24م و64م = 88م.","key_points":["هذه حسابات تعليمية تقريبية وليست قياسًا لأكورد","رد الفعل يستغرق وقتًا تتحرك خلاله السيارة","زيادة السرعة ترفع مسافة الفرملة بشدة"],"scenario":"تسيرين بسرعة 80 كم/ساعة وفق النموذج التعليمي الوارد في الدليل.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"زيادة السرعة ترفع مسافة الفرملة بشدة"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-027','WK-09',27,'مسافة الأمان وقاعدة الثانيتين',35,'{"goal":"قياس الفاصل الآمن زمنيًا","introduction":"قيسي الفرق الزمني عندما تتجاوز سيارة أمامك علامة ثابتة ثم تصل سيارتك إليها. قاعدة الثانيتين حد تعليمي أدنى في ظروف ملائمة؛ زيدي الفاصل عند الخطر.","key_points":["لا تخلطي بين مسافة التتابع ومسافة التوقف","الطريق المبتل يحتاج هامشًا أكبر","العد يعتمد على نقطة ثابتة وليس النظر للأمتار فقط"],"scenario":"بدأ المطر والطريق مزدحم.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"العد يعتمد على نقطة ثابتة وليس النظر للأمتار فقط"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-028','WK-10',28,'القيادة الوقائية واكتشاف الأخطار',35,'{"goal":"تطبيق دورة رصد الخطر والتصرف","introduction":"استعملي تسلسلًا تدريبيًا: ألاحظ ← أتوقع ← أقرر ← أتصرف. الهدف اتخاذ قرار بناء على مؤشر مرئي وليس التخمين.","key_points":["فرّقي بين الملاحظة والتوقع","خططي لطريق خروج آمن عند احتمال الخطر","راقبي مناطق تحجبها المركبات المتوقفة"],"scenario":"كرة تظهر من خلف سيارة عند حديقة.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"راقبي مناطق تحجبها المركبات المتوقفة"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-029','WK-10',29,'عادات القيادة الخطرة',35,'{"goal":"تمييز العادات التي ترفع خطر الحوادث","introduction":"التشتت والنعاس والسرعة العدوانية والالتصاق بالمركبة الأمامية كلها ممارسات تزيد الخطر.","key_points":["لا تستخدمي الهاتف أثناء القيادة","توقفي في مكان آمن عند النعاس","لا تردي على سائق ملتصق خلفك بفرملة انتقامية"],"scenario":"سائق خلفك يقترب جدًا منك.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا تردي على سائق ملتصق خلفك بفرملة انتقامية"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-030','WK-10',30,'اختبارات اكتشاف الأخطار بالفيديو',35,'{"goal":"فهم الفرق بين تدريب إدراك الأخطار والقيادة","introduction":"اختبارات الفيديو تعلّمك ملاحظة المؤشرات المبكرة وتوقيت القرار، لكنها لا تعوّض التمرين العملي تحت إشراف مناسب.","key_points":["انتبهي لما يتغير داخل المشهد","اذكري سبب توقعك للخطر","لا تساوي بين نجاح الاختبار البصري وإتقان التوجيه أو الفرملة"],"scenario":"نجحتِ في اختبار فيديو للتنبؤ بالخطر.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا تساوي بين نجاح الاختبار البصري وإتقان التوجيه أو الفرملة"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-031','WK-11',31,'أنواع المواقف',35,'{"goal":"التعرف على أشكال مواقف السيارات","introduction":"المواقف الشائعة: موازية ومائلة وعمودية. الركن للخلف أسلوب للدخول وليس نوع موقف مستقل.","key_points":["تأكدي من أن المكان يسمح بوقوف السيارة","انتبهي إلى الأبواب والمشاة وخطوط التحديد","اختاري مكانًا أوسع عند التدريب الأول"],"scenario":"سيارة تدخل موقفًا عموديًا بالرجوع للخلف.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"اختاري مكانًا أوسع عند التدريب الأول"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-032','WK-11',32,'الرجوع للخلف',35,'{"goal":"إدراك مسار المركبة وحدود الكاميرا","introduction":"عند الرجوع تتجه مؤخرة السيارة غالبًا نحو جهة تدوير المقود، مع تأرجح محتمل للمقدمة في الجهة الأخرى.","key_points":["الكاميرا لا تعرض جميع المناطق الخلفية","تحققي بصريًا من المحيط والمرايا","نفذي الرجوع ببطء وتحت إشراف عملي مناسب"],"scenario":"الكاميرا تعرض المسار خلفك دون عوائق.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"نفذي الرجوع ببطء وتحت إشراف عملي مناسب"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-033','WK-11',33,'الخروج من الموقف بالرجوع للخلف',35,'{"goal":"الخروج الآمن من الموقف بالخلف","introduction":"يتطلب الخروج فحص الممر وحركة المشاة ومقدمة السيارة أيضًا، لأن دورانها قد يقربها من المركبات المجاورة.","key_points":["استعدي لاحتمال مرور مشاة خلف السيارة","خروج الموقف المائل يختلف عن العمودي","لا تتعجلي وتوقفي عند أي خطر"],"scenario":"تراجعين والمقدمة اقتربت من سيارة بجوارك.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا تتعجلي وتوقفي عند أي خطر"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-034','WK-12',34,'الركن الموازي',35,'{"goal":"فهم خطوات الركن الموازي بشكل مفاهيمي","introduction":"ابدئي من مكان آمن ومسموح، وافحصي المسافة بين السيارات والمشاة، ثم تقدمي تدريجيًا في المناورة مع الإشارات والفحص.","key_points":["اتجاه المناورة يختلف بين السير على اليمين واليسار","لا تحفظي نقاط لف مقود من سيارة أخرى حرفيًا","أكملي التمركز دون إعاقة الحركة أو احتكاك"],"scenario":"فيديو أجنبي يركن بمحاذاة الرصيف الأيسر.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"أكملي التمركز دون إعاقة الحركة أو احتكاك"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-035','WK-12',35,'مناورات X وT وY',35,'{"goal":"تمييز المناورات التعليمية دون تعميم اختبارها","introduction":"قد تستخدم بعض المدارس مسميات X وT وY و90 للمناورات. شكل التدريب والاختبار يختلف باختلاف المدرسة.","key_points":["تعلمي مفاهيم الرجوع والدوران متعدد النقاط","راجعي تعليمات مدرستك قبل حفظ أسماء المناورات","نقاط المرجع الدقيقة تُتعلّم بمركبة التدريب"],"scenario":"صديقة تقول إن كل مدارس السعودية تختبر Y بنفس الرسم.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"نقاط المرجع الدقيقة تُتعلّم بمركبة التدريب"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-036','WK-12',36,'المرتفعات وفرامل التوقف',35,'{"goal":"الفصل بين P وفرامل التوقف ومساعدات التوقف","introduction":"في الأوتوماتيك، وضع P يختلف عن فرامل التوقف، كما أن Brake Hold يختلف عن Hill Start Assist.","key_points":["Brake Hold ليس تأمينًا للسيارة المتروكة","اتّبعي دليل أكورد الفعلية لإجراءات الركن","لا تبدلي بين D وR قبل التوقف الكامل"],"scenario":"تريدين ترك سيارة أوتوماتيكية مركونة على منحدر.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا تبدلي بين D وR قبل التوقف الكامل"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-037','WK-13',37,'المطر والتماسك ومسافة الأمان',35,'{"goal":"تعديل القيادة في المطر","introduction":"المطر يقلل الرؤية وقد يقلل التماسك. حافظي على خط سير مستقر وتجنبي تجمعات المياه غير المعروفة العمق.","key_points":["خففي السرعة بشكل مناسب","اتركي مسافة إضافية لتفادي الكبح المفاجئ","الانزلاق المائي ليس مرادفًا لكل انزلاق على سطح مبتل"],"scenario":"أمامك تجمع ماء لا تستطيعين تقدير عمقه.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"الانزلاق المائي ليس مرادفًا لكل انزلاق على سطح مبتل"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-038','WK-13',38,'الغبار والضباب',35,'{"goal":"اختيار الأنوار والاستجابة لضعف الرؤية","introduction":"في الضباب والغبار خففي السرعة وزيدي الفاصل واستخدمي النور المنخفض عند الحاجة، وتجنبي العالي الذي قد يزيد الوهج.","key_points":["الفلشر ليس بديلًا عن الأنوار المطلوبة","عند سوء الرؤية الشديد قد يكون تأجيل الرحلة الأفضل","لا تتوقفي فجأة داخل مسار سير سريع"],"scenario":"ضباب كثيف ونورك العالي يزيد انعكاس الضوء أمامك.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"لا تتوقفي فجأة داخل مسار سير سريع"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-039','WK-13',39,'القيادة الليلية وأنواع الأنوار',35,'{"goal":"التفريق بين النور العالي والمنخفض والتحذيري","introduction":"النور المنخفض للإضاءة الأساسية دون إبهار، والعالي يوسّع المدى في ظروف تسمح، وأضواء التحذير تنبّه إلى خطر.","key_points":["لا تستخدمي العالي أمام مركبات مقابلة","أنوار الموضع وحدها ليست بديلًا عن أنوار السير اللازمة","تأكدي من المصابيح المناسبة لحالة الطقس والطريق"],"scenario":"تقابلين مركبة ليلًا على طريق غير مضاء.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"تأكدي من المصابيح المناسبة لحالة الطقس والطريق"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-040','WK-14',40,'تعطل السيارة على الطريق',35,'{"goal":"التصرف الآمن عند تعطل السيارة","introduction":"الأولوية للتحكم بالمركبة والوصول إلى موضع أكثر أمانًا إن أمكن ثم طلب المساعدة. خطة الخروج تعتمد على موقع التعطل والخطر.","key_points":["لا تنزلي فورًا إذا كان الخروج يعرضك لحركة خطرة","لا تضعي مثلثًا إذا كان الوصول لمكانه غير آمن","إذا ظهر دخان أو حريق فتعاملي مع الخطر الطارئ واطلبي النجدة"],"scenario":"تعطلتِ بجانب طريق سريع والخروج إلى حركة المرور خطير.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"إذا ظهر دخان أو حريق فتعاملي مع الخطر الطارئ واطلبي النجدة"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-041','WK-14',41,'لمبات التحذير في هوندا',35,'{"goal":"قراءة مؤشرات الزيت والحرارة والفرامل","introduction":"هناك فرق بين مؤشر حالة ورسالة فحص وتحذير خطير. دليل سنة موديل أكورد الفعلي هو المرجع لتصرف دقيق.","key_points":["انخفاض ضغط زيت المحرك قد يستوجب التوقف الآمن سريعًا","حرارة المحرك العالية خطر ولا تفتحي غطاء الرديتر وهو ساخن","ضوء الفرامل الأحمر قد يرتبط بفرامل التوقف أو مشكلة أخرى"],"scenario":"ظهر تحذير ضغط زيت المحرك أثناء التشغيل.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"ضوء الفرامل الأحمر قد يرتبط بفرامل التوقف أو مشكلة أخرى"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-042','WK-14',42,'الحوادث وأرقام الطوارئ',35,'{"goal":"التفريق بين الحوادث الطارئة وحوادث الأضرار المادية","introduction":"في حالة إصابة أو خطر فوري اطلبي خدمة الطوارئ الملائمة. ليست جميع الحوادث من اختصاص نجم.","key_points":["في مناطق 911 المغطاة يمكن الاتصال بالعمليات الأمنية الموحدة","997 رقم الإسعاف و993 المرور و996 أمن الطرق","للإبلاغ عن حادث مشمول بخدمة نجم راجعي شروطها وقنواتها الرسمية"],"scenario":"حادث فيه مصاب في مكة ويحتاج مساعدة فورية.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"للإبلاغ عن حادث مشمول بخدمة نجم راجعي شروطها وقنواتها الرسمية"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-043','WK-15',43,'مراجعة الإشارات والخطوط',35,'{"goal":"استعادة فهم الإشارات والخطوط","introduction":"راجعي المعنى من شكل العلامة ورمزها وموقعها، وطبقيه على طريق محدد بدل تعميم اللون أو شكل الخط وحده.","key_points":["الخط المتقطع لا يلغي السلامة","علامة قف تتطلب توقفًا تامًا","السهم الأرضي قد يقيد اتجاه المسار"],"scenario":"خط متقطع بين مسارين وتريدين تغيير المسار.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"السهم الأرضي قد يقيد اتجاه المسار"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-044','WK-15',44,'الأولوية والتقاطعات والدوارات',35,'{"goal":"حل سيناريو الأولوية كاملًا","introduction":"حددي أولًا هل هناك تنظيم للإشارة، ثم افحصي نوع الطريق والدوار والمشاة، ثم اتخذي قرارًا واضحًا.","key_points":["أولوية الداخل في الدوار المعتاد","أولوية المشاة على معبرهم","القادم من اليمين ينطبق ضمن شروط محددة"],"scenario":"هناك مشاة يعبرون عند مخرج دوار بينما أنت داخل الدوار.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"القادم من اليمين ينطبق ضمن شروط محددة"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-045','WK-15',45,'السرعة والمخاطر والطوارئ',35,'{"goal":"الربط بين السرعة ومسافة الأمان والطوارئ","introduction":"السرعة الفعلية والظروف والتشتت والفاصل بين السيارات عوامل متداخلة. أي اختبار شامل يجب أن يقيّم القرار لا المصطلح فقط.","key_points":["قاعدة الثانيتين حد أولي تعليمي","الطريق المبتل قد يزيد مسافة التوقف","التشتت يقلل القدرة على إدراك الخطر مبكرًا"],"scenario":"تسيرين بسرعة 60 مع انشغال بالجوال.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"التشتت يقلل القدرة على إدراك الخطر مبكرًا"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-046','WK-16',46,'إجراءات إصدار الرخصة',35,'{"goal":"فهم مراحل استخراج الرخصة في السعودية","introduction":"الحجز في أبشر خطوة للحصول على التدريب، وليس إصدار رخصة فورية. هناك فحص طبي وتدريب واختبارات وإجراءات دفع.","key_points":["الحد الأدنى لرخصة القيادة الخاصة 18 سنة بحسب بطاقة الخدمة","يمكن حجز موعد مدرسة معتمدة عبر أبشر","الرسوم الحكومية منفصلة عن رسوم التدريب"],"scenario":"حجزتِ موعدًا بمدرسة معتمدة عبر أبشر.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"الرسوم الحكومية منفصلة عن رسوم التدريب"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-047','WK-16',47,'برامج التدريب والاختبارات',35,'{"goal":"فهم مستويات برامج تعليم القيادة","introduction":"تختلف البرامج بحسب تقييم المدرسة للمستوى. مثال مدرسة جدة المتطورة يعرض مسارات 30 و15 و6 ساعات بتكاليف مختلفة.","key_points":["البرنامج الأطول موجّه عادةً لمن تبدأ من الصفر","الساعات ومحتوى البرنامج تختلف بحسب المدرسة والسياسات الجارية","الرسوم المنشورة قابلة للتغيير فراجعي المدرسة قبل الدفع"],"scenario":"متدربة جديدة لم تتعلم القيادة قط.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"الرسوم المنشورة قابلة للتغيير فراجعي المدرسة قبل الدفع"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.lessons(id,week_id,lesson_number,title,estimated_minutes,content,publication_status) VALUES ('LES-048','WK-16',48,'الاستعداد للاختبار النهائي وما بعد الرخصة',35,'{"goal":"الاستعداد للدراسة والاختبارات وما بعدها","introduction":"الاستعداد الجيد يجمع فهم اللوحات ومهارة اتخاذ القرار والتدريب النظامي العملي. لا يعتبر نجاح اختبار تدريبي في هذا الموقع إصدارًا للرخصة.","key_points":["راجعي مواضع أخطائك بدل إعادة الإجابات عشوائيًا","جهزي الأوراق والمتطلبات المعتمدة من مدرستك","بعد الحصول على الرخصة استمري في القيادة الوقائية والتعلم"],"scenario":"أجبتِ عن جميع أسئلة موقعنا بنجاح.","practice":"اقرئي الموقف وحاولي صياغة القرار بصوتك، ثم اختاري الإجابة وراجعي سببها.","recap":"بعد الحصول على الرخصة استمري في القيادة الوقائية والتعلم"}'::jsonb,'draft') ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content,estimated_minutes=EXCLUDED.estimated_minutes;
INSERT INTO public.sources(id,title,url,category,provenance) VALUES ('S001','نظام المرور السعودي — هيئة الخبراء','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/85364e57-c01e-41ba-8def-a9a700f183e9/1','تشريعي','{"scope":"قواعد السير والرخص","notes":"ينبغي فحص اللائحة والتعديلات السارية لكل حكم قبل نشره","check":"رابط صفحة محددة جرى التحقق منها في هذه الجولة"}'::jsonb) ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,url=EXCLUDED.url,provenance=EXCLUDED.provenance;
INSERT INTO public.sources(id,title,url,category,provenance) VALUES ('S002','أبشر — بطاقة خدمة إصدار رخصة القيادة','https://www.absher.sa/wps/portal/individuals/static/guide/service-contents/','خدمة رسمية','{"scope":"مواعيد التدريب والمتطلبات","notes":"الصفحة الأصلية ذات مسار ديناميكي طويل؛ راجعي البطاقة عند النشر","check":"تحقق من بطاقة الخدمة؛ الرابط هنا مدخل رسمي وقد يحتاج التنقل للبطاقة"}'::jsonb) ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,url=EXCLUDED.url,provenance=EXCLUDED.provenance;
INSERT INTO public.sources(id,title,url,category,provenance) VALUES ('S003','الهيئة العامة للطرق — مدلولات الخطوط الطولية عبر واس','https://www.spa.gov.sa/N2145384','جهة رسمية','{"scope":"دلالات الخطوط الأرضية","notes":"خبر رسمي داعم، وليس بديلًا عن أحدث مواصفة أو تشريع","check":"رابط خبر محدد، تاريخ 2024-07-28"}'::jsonb) ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,url=EXCLUDED.url,provenance=EXCLUDED.provenance;
INSERT INTO public.sources(id,title,url,category,provenance) VALUES ('S004','هوندا — دليل أكورد 2025 (نسخة الولايات المتحدة)','https://techinfo.honda.com/rjanisis/pubs/OM/AH/A30A2525IOM/enu/details/menulist.html','دليل الشركة','{"scope":"أمثلة على أنظمة المركبة","notes":"غير مثبت أنه يطابق سيارة التدريب؛ لا تُعمم خصائص الفئة أو المنطقة","check":"رابط دليل رسمي محدد"}'::jsonb) ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,url=EXCLUDED.url,provenance=EXCLUDED.provenance;
INSERT INTO public.sources(id,title,url,category,provenance) VALUES ('S005','دلة — مرجع القيادة النظري المشار إليه في التدقيق','https://ddc.sa/','دليل تدريبي','{"scope":"الإشارات والمناورات والسلامة","notes":"يلزم التحقق من رابط PDF والطبعة وحقوق إعادة الاستخدام","check":"عنوان نطاق فقط؛ لم يسترجع الرابط المباشر للطبعة الأصلية"}'::jsonb) ON CONFLICT(id) DO UPDATE SET title=EXCLUDED.title,url=EXCLUDED.url,provenance=EXCLUDED.provenance;
